{{- if not .Values.rollout.enabled }}
apiVersion: apps/v1
kind: Deployment
# ... the existing template, unchanged ...
{{- end }}

{{- if .Values.rollout.enabled }}
apiVersion: argoproj.io/v1alpha1
kind: Rollout
metadata:
  name: {{ .Release.Name }}
  labels:
    app.kubernetes.io/name: {{ .Chart.Name }}
    app.kubernetes.io/instance: {{ .Release.Name }}
spec:
  replicas: {{ .Values.replicaCount }}
  revisionHistoryLimit: 3
  selector:
    matchLabels:
      app.kubernetes.io/instance: {{ .Release.Name }}
  template:
    metadata:
      labels:
        app.kubernetes.io/name: {{ .Chart.Name }}
        app.kubernetes.io/instance: {{ .Release.Name }}
    spec:
      containers:
        - name: app
          image: "{{ .Values.image.repository }}{{ if .Values.image.digest }}@{{ .Values.image.digest }}{{ else }}:{{ .Values.image.tag }}{{ end }}"
          ports:
            - name: http
              containerPort: {{ .Values.service.targetPort }}
          env:
            {{- range $k, $v := .Values.env }}
            - name: {{ $k }}
              value: {{ $v | quote }}
            {{- end }}
          readinessProbe:
            httpGet: {path: /health, port: http}
            periodSeconds: 5
          resources: {{- toYaml .Values.resources | nindent 12 }}
  strategy:
    canary:
      stableService: {{ .Release.Name }}
      canaryService: {{ .Release.Name }}-canary
      trafficRouting:
        nginx:
          stableIngress: {{ .Release.Name }}
      {{- if .Values.rollout.analysis.enabled }}
      analysis:
        templates:
          - templateName: {{ .Release.Name }}-canary-vs-stable
        startingStep: {{ .Values.rollout.analysis.startingStep }}
        args:
          - name: canary-hash
            valueFrom: {podTemplateHashValue: Latest}
          - name: stable-hash
            valueFrom: {podTemplateHashValue: Stable}
      {{- end }}
      steps: {{- toYaml .Values.rollout.steps | nindent 8 }}
{{- end }}

{{- if .Values.rollout.enabled }}
apiVersion: v1
kind: Service
metadata:
  name: {{ .Release.Name }}-canary
  labels:
    app.kubernetes.io/name: {{ .Chart.Name }}
    app.kubernetes.io/instance: {{ .Release.Name }}
spec:
  selector:
    app.kubernetes.io/instance: {{ .Release.Name }}
  ports:
    - name: http
      port: {{ .Values.service.port }}
      targetPort: http
{{- end }}

